def apply_review(bank):
 for q in bank:
  if not q['id'].startswith('D3-C-'):continue
  n=int(q['id'].rsplit('-',1)[1])
  if n in REVIEW_SOURCES:q.update(source=REVIEW_SOURCES[n],version=2)

def build(bank,sets):
 if any(s['id']=='D3-C' for s in sets):
  apply_review(bank);return
