  topic='Day 1 종합' if n<=10 else 'Day 2 종합' if n<=20 else '에이전트와 도구' if n<=28 else '텍스트·음성'
  q=copy.deepcopy(base[derived]);q.update(id=f'D3-C-{n:02}',version=1,prompt=prompt,type='multiple' if len(answers)>1 else 'single',options=[dict(id=chr(97+i),text=t,reason=r) for i,(t,r,c) in enumerate(options)],correct=[chr(97+i) for i,(t,r,c) in enumerate(options) if c],explanation=' '.join(r for t,r,c in options if c),topic=topic,lecture=f'Day {1 if n<=10 else 2 if n<=20 else 3} 전체',lab='Day 1~3 종합',difficulty='종합 응용·요구조건 비교',derivedFrom=derived,reviewedAt='2026-10-28')
  q.pop('code',None);q.pop('slideRefs',None)
